begin;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();suffix text:=substr(replace(gen_random_uuid()::text,'-',''),1,8);
 r jsonb;t jsonb;s jsonb;request uuid;listing text;second_listing text;balance bigint;copies integer;rev bigint;booster uuid;pool text[];
begin
 insert into auth.users(id,email,is_anonymous) values(a,'econ-a-'||suffix||'@example.invalid',false),(b,'econ-b-'||suffix||'@example.invalid',false),(c,'econ-c-'||suffix||'@example.invalid',false);
 insert into public.kizuna_profiles(id,username) values(a,'EconA_'||suffix),(b,'EconB_'||suffix),(c,'EconC_'||suffix);
 perform set_config('request.jwt.claim.sub',a::text,true);
 r:=public.kizuna_economy('get');
 if r#>>'{snapshot,chakra}'<>'500' or r#>>'{snapshot,stock,free}'<>'3' then raise exception 'Starting economy incorrect';end if;
 request:=gen_random_uuid();r:=public.kizuna_economy('open','{"count":1,"booster":"mix"}',request);
 t:=public.kizuna_economy('open','{"count":1,"booster":"mix"}',request);
 if jsonb_array_length(r#>'{snapshot,owned}')<>5 or r#>'{result,cards}'<>t#>'{result,cards}' or t#>>'{snapshot,stock,free}'<>'2' then raise exception 'Draw replay duplicates';end if;
 begin perform public.kizuna_economy('shop','{"count":1}',request);raise exception 'Reused request accepted';exception when raise_exception then if sqlerrm<>'REQUEST_REUSED' then raise;end if;end;
 begin perform public.kizuna_economy('open','{"count":0,"booster":"mix"}',gen_random_uuid());raise exception 'Invalid count accepted';exception when raise_exception then if sqlerrm<>'INVALID_QUANTITY' then raise;end if;end;
 begin perform public.kizuna_economy('open','{"count":10,"booster":"mix"}',gen_random_uuid());raise exception 'Missing packs accepted';exception when raise_exception then if sqlerrm<>'INSUFFICIENT_PACKS' then raise;end if;end;
 r:=public.kizuna_economy('daily','{}',gen_random_uuid());
 begin perform public.kizuna_economy('daily','{}',gen_random_uuid());raise exception 'Daily twice';exception when raise_exception then if sqlerrm<>'DAILY_CLAIMED' then raise;end if;end;
 r:=public.kizuna_economy('shop','{"count":1}',gen_random_uuid());if r#>>'{snapshot,chakra}'<>'400' then raise exception 'Wrong shop price';end if;
 -- Deterministic fixtures are privileged and rolled back, never available to browsers.
 update public.kizuna_player_states set snapshot=jsonb_set(jsonb_set(snapshot,'{owned}','[{"id":"cseed-0013","at":1700000000000},{"id":"cseed-0013","at":1700000000001},{"id":"cseed-0014","at":1700000000002}]'),'{chakra}','10000') where user_id=a;
 r:=public.kizuna_economy('get');rev:=(r->>'revision')::bigint;
 r:=public.kizuna_economy('recycle_all',jsonb_build_object('revision',rev),gen_random_uuid());if jsonb_array_length(r#>'{snapshot,owned}')<>2 or r#>>'{snapshot,chakra}'<>'10060' then raise exception 'Recycle duplicates';end if;
 request:=gen_random_uuid();r:=public.kizuna_economy('publish','{"cardId":"cseed-0013","mode":"sale","hours":24,"price":100}',request);listing:=r#>>'{result,listingId}';
 if jsonb_array_length(r#>'{snapshot,owned}')<>1 or jsonb_array_length(r#>'{snapshot,market,listings}')<>1 then raise exception 'Escrow not mirrored';end if;
 t:=public.kizuna_economy('publish','{"cardId":"cseed-0013","mode":"sale","hours":24,"price":100}',request);if t#>>'{result,listingId}'<>listing then raise exception 'Publish duplicated';end if;
 begin perform public.kizuna_economy('buy',jsonb_build_object('id',listing),gen_random_uuid());raise exception 'Self buy';exception when raise_exception then if sqlerrm<>'SELF_TRADE' then raise;end if;end;
 r:=public.kizuna_economy('publish','{"cardId":"cseed-0014","mode":"trade","hours":24,"wants":["cseed-0013"]}',gen_random_uuid());second_listing:=r#>>'{result,listingId}';
 perform set_config('request.jwt.claim.sub',b::text,true);r:=public.kizuna_economy('get');
 r:=public.kizuna_economy('browse');if not exists(select 1 from jsonb_array_elements(r#>'{result,listings}') x where x->>'id'=listing and x->'reservedCopy'='null') then raise exception 'Shared listing or privacy incorrect';end if;
 request:=gen_random_uuid();r:=public.kizuna_economy('buy',jsonb_build_object('id',listing),request);t:=public.kizuna_economy('buy',jsonb_build_object('id',listing),request);
 if r#>>'{snapshot,chakra}'<>'400' or jsonb_array_length(t#>'{snapshot,owned}')<>1 then raise exception 'Buy debited twice';end if;
 begin perform public.kizuna_economy('buy',jsonb_build_object('id',listing),gen_random_uuid());raise exception 'Sold listing reused';exception when raise_exception then if sqlerrm<>'LISTING_UNAVAILABLE' then raise;end if;end;
 if (select snapshot#>>'{market,listings,0,reservedCopy,id}' from public.kizuna_player_states where user_id=a)<>'cseed-0014' then raise exception 'Counterparty write hid remaining escrow';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);r:=public.kizuna_economy('cancel',jsonb_build_object('id',second_listing),gen_random_uuid());
 if r#>>'{snapshot,chakra}'<>'10153' or jsonb_array_length(r#>'{snapshot,market,listings}')<>0 then raise exception 'Seller proceeds or stale escrow';end if;
 r:=public.kizuna_economy('publish','{"cardId":"cseed-0014","mode":"auction","hours":12,"price":100}',gen_random_uuid());listing:=r#>>'{result,listingId}';
 perform set_config('request.jwt.claim.sub',b::text,true);r:=public.kizuna_economy('bid',jsonb_build_object('id',listing,'amount',100),gen_random_uuid());
 perform set_config('request.jwt.claim.sub',c::text,true);r:=public.kizuna_economy('get');r:=public.kizuna_economy('bid',jsonb_build_object('id',listing,'amount',101),gen_random_uuid());
 if (select snapshot->>'chakra' from public.kizuna_player_states where user_id=b)<>'400' then raise exception 'Outbid not refunded';end if;
 r:=public.kizuna_economy('buy',jsonb_build_object('id',listing),gen_random_uuid());if r#>>'{snapshot,chakra}'<>'300' then raise exception 'Own bid not netted from buy now';end if;
 perform set_config('request.jwt.claim.sub',b::text,true);r:=public.kizuna_economy('publish','{"cardId":"cseed-0013","mode":"trade","hours":24,"wants":["cseed-0014"]}',gen_random_uuid());listing:=r#>>'{result,listingId}';
 perform set_config('request.jwt.claim.sub',c::text,true);r:=public.kizuna_economy('trade',jsonb_build_object('id',listing,'cardId','cseed-0014'),gen_random_uuid());
 if r#>>'{snapshot,owned,0,id}'<>'cseed-0013' or r#>>'{snapshot,chakra}'<>'300' or (select snapshot#>>'{owned,0,id}' from public.kizuna_player_states where user_id=b)<>'cseed-0014' then raise exception 'Trade not atomic';end if;
 r:=public.kizuna_economy('publish','{"cardId":"cseed-0013","mode":"sale","hours":12,"price":100}',gen_random_uuid());listing:=r#>>'{result,listingId}';
 r:=public.kizuna_economy('cancel',jsonb_build_object('id',listing),gen_random_uuid());if r#>>'{snapshot,owned,0,at}'<>'1700000000000' then raise exception 'Original copy date lost';end if;
 update public.kizuna_player_states set snapshot=jsonb_set(jsonb_set(jsonb_set(snapshot,'{stock,free}','99'),'{stock,t}',to_jsonb(floor(extract(epoch from now())*1000)::bigint-21600000*2::bigint)),'{stock,pm}','249') where user_id=c;
 r:=public.kizuna_economy('get');if r#>>'{snapshot,stock,free}'<>'100' then raise exception 'Refill cap';end if;
 r:=public.kizuna_economy('open','{"count":1,"booster":"mix"}',gen_random_uuid());if not exists(select 1 from jsonb_array_elements(r#>'{result,cards}') x where x->>'rarity'='Mythique') then raise exception 'Mythic pity missing';end if;

 update public.kizuna_player_states set snapshot=jsonb_set(jsonb_set(snapshot,'{stock,free}','100'),'{stock,pl}','49') where user_id=c;
 r:=public.kizuna_economy('open','{"count":10,"booster":"mix"}',gen_random_uuid());
 if jsonb_array_length(r#>'{result,cards}')<>50 then raise exception 'Batch size incorrect';end if;
 if exists(select 1 from jsonb_array_elements(r#>'{result,cards}') with ordinality x where (value->>'level')::integer<case when (ordinality-1)%5=4 then 3 when (ordinality-1)%5=3 then 2 else 1 end) then raise exception 'Slot guarantee missing';end if;
 if (r#>>'{result,cards,4,level}')::integer<5 then raise exception 'Legendary pity missing';end if;
 select array_agg(id) into pool from (select distinct on (card->>'rarity') id from public.kizuna_cards where card->>'rarity' in ('Commun','Rare','Mythique') order by card->>'rarity',id) x;
 insert into public.kizuna_boosters(name,description,card_ids,card_count,published) values('QA economy pool','rollback only',pool,5,true) returning id into booster;
 r:=public.kizuna_economy('open',jsonb_build_object('count',1,'booster','staff:'||booster),gen_random_uuid());
 if exists(select 1 from jsonb_array_elements(r#>'{result,cards}') x where not(x->>'id'=any(pool))) then raise exception 'Custom pool escaped';end if;
 r:=public.kizuna_economy('publish','{"cardId":"cseed-0013","mode":"auction","hours":12,"price":100}',gen_random_uuid());listing:=r#>>'{result,listingId}';
 perform set_config('request.jwt.claim.sub',b::text,true);r:=public.kizuna_economy('bid',jsonb_build_object('id',listing,'amount',100),gen_random_uuid());
 update kizuna_private.kizuna_market_listings set ends_at=now()-interval '1 second' where id=listing::uuid;
 r:=public.kizuna_economy('get');if (select status from kizuna_private.kizuna_market_listings where id=listing::uuid)<>'sold' or not exists(select 1 from jsonb_array_elements(r#>'{snapshot,owned}') x where x->>'id'='cseed-0013') then raise exception 'Expired auction not settled';end if;
 r:=public.kizuna_economy('publish','{"cardId":"cseed-0014","mode":"sale","hours":12,"price":100}',gen_random_uuid());listing:=r#>>'{result,listingId}';
 update kizuna_private.kizuna_market_listings set ends_at=now()-interval '1 second' where id=listing::uuid;
 r:=public.kizuna_economy('get');if (select status from kizuna_private.kizuna_market_listings where id=listing::uuid)<>'ended' or not exists(select 1 from jsonb_array_elements(r#>'{snapshot,owned}') x where x->>'id'='cseed-0014' and x->>'at'='1700000000002') then raise exception 'Expired sale lost original copy';end if;
 perform set_config('request.jwt.claim.sub','',true);
 begin perform public.kizuna_economy('get');raise exception 'Anonymous economy';exception when insufficient_privilege then null;end;
end; $$;
rollback;
